# @used-by :func:`dfh_ensure_builtin_plugins()`
def _register_builtins() -> None:
	from agent_tools.arch.review_cli import register_arch_commands
	_register_analysis_builtins()
	_register_runtime_builtins()
	register_arch_commands(dfh_register_command)
